package main

import (
    "crypto/sha256"
    "encoding/hex"
    "fmt"
    "log"
    "net/http"
    "os"
    "path/filepath"
    "regexp"
    "strings"
)

func main() {
    base := "/opt/registry"
    pattern := regexp.MustCompile("^sha256:[0-9a-f]{64}$")
    manifest, err := os.ReadFile(filepath.Join(base,"manifest"))
    if err != nil { log.Fatal(err) }
    hash := sha256.Sum256(manifest)
    digest := "sha256:" + hex.EncodeToString(hash[:])
    http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
        w.Header().Set("Docker-Distribution-Api-Version","registry/2.0")
        p := strings.Split(strings.Trim(r.URL.Path,"/"),"/")
        if r.URL.Path == "/v2/" { fmt.Fprint(w,"{}"); return }
        if len(p)<4 || p[0]!="v2" { http.NotFound(w,r); return }
        item := p[len(p)-1]
        switch p[len(p)-2] {
        case "manifests":
            if item!="3.20" && item!=digest { http.NotFound(w,r); return }
            w.Header().Set("Content-Type","application/vnd.oci.image.manifest.v1+json")
            w.Header().Set("Docker-Content-Digest",digest)
            http.ServeFile(w,r,filepath.Join(base,"manifest"))
        case "blobs":
            if !pattern.MatchString(item) { http.NotFound(w,r); return }
            w.Header().Set("Docker-Content-Digest",item)
            http.ServeFile(w,r,filepath.Join(base,strings.TrimPrefix(item,"sha256:")))
        default:
            http.NotFound(w,r)
        }
    })
    log.Fatal(http.ListenAndServe("127.0.0.1:5000",nil))
}
